        (0xffb53a50b9920d4cc686d1147a9bf8f6f2ce9f62),
        (0xffe52568fb0e7038ef289677288bb704e5c9e82e),
        (0xffe691a6ddb5d2645321e0a920c2e7bdd00dd3d8)
),

-- label_ids: Dune identifier labels (what the address IS), e.g. 'Uniswap V3: Router'
label_ids as (
    select
        l.address,
        array_join(array_agg(distinct l.name), ' | ') as dune_label_name,
        array_join(array_agg(distinct l.category), ' | ') as dune_label_category
    from labels.addresses as l
    inner join universe as u on u.address = l.address
    where l.blockchain = 'optimism'
        and l.label_type = 'identifier'
    group by 1
),

-- label_personas: Dune persona labels (what the address BEHAVES like), e.g. MEV bot
label_personas as (
    select
        l.address,
        array_join(array_agg(distinct l.name), ' | ') as dune_persona
    from labels.addresses as l
    inner join universe as u on u.address = l.address
    where l.blockchain = 'optimism'
        and l.label_type = 'persona'
    group by 1
),

-- decoded: Dune's decoded contract registry (project namespace + contract name)
decoded as (
    select
        c.address,
        array_join(array_agg(distinct c.namespace), ' | ') as dune_namespace,
        array_join(array_agg(distinct c.name), ' | ') as dune_contract_name
    from optimism.contracts as c
    inner join universe as u on u.address = c.address
    group by 1
),

-- owners: Dune entity ownership registry
owners as (
    select
        o.address,
        array_join(array_agg(distinct o.custody_owner), ' | ') as dune_owner
    from labels.owner_addresses as o
    inner join universe as u on u.address = o.address
    where o.blockchain = 'optimism'
    group by 1
),

-- tokens: ERC20 token symbol, if the address is a token contract
tokens as (
    select
        t.contract_address as address,
        max(t.symbol) as dune_token_symbol
    from tokens.erc20 as t
    inner join universe as u on u.address = t.contract_address
    where t.blockchain = 'optimism'
    group by 1
),

-- cex: exchange-owned wallets
cex as (
    select
        x.address,
        array_join(array_agg(distinct x.cex_name), ' | ') as dune_cex_name
    from cex.addresses as x
    inner join universe as u on u.address = x.address
    where x.blockchain = 'optimism'
    group by 1
)

select
    u.address,
    li.dune_label_name,
    li.dune_label_category,
    lp.dune_persona,
    d.dune_namespace,
    d.dune_contract_name,
    o.dune_owner,
    t.dune_token_symbol,
    x.dune_cex_name
from universe as u
left join label_ids as li on li.address = u.address
left join label_personas as lp on lp.address = u.address
left join decoded as d on d.address = u.address
left join owners as o on o.address = u.address
left join tokens as t on t.address = u.address
left join cex as x on x.address = u.address
order by u.address
